import{_ as t,o as e,c as n,a6 as r}from"./chunks/framework.DycQjAfF.js";const m=JSON.parse('{"title":"Kode Barang","description":"Struktur nomor material 9 karakter dan cara menulis deskripsi material sesuai standar cataloguing Warehouse BPI.","frontmatter":{"title":"Kode Barang","description":"Struktur nomor material 9 karakter dan cara menulis deskripsi material sesuai standar cataloguing Warehouse BPI.","status":"ditinjau","dasar":"Standard Penomoran dan Deskripsi Material Cataloguing Warehouse BPI, serta materi presentasi Gudang Teknik (slide 11)","diperbarui":"2026-10-20T00:00:00.000Z","kategori":"Gudang Teknik","sumber":["ik-gudang-teknik","ppt-gudang-teknik"],"kata_kunci":["kode barang","nomor material","material number","cataloguing","material type","material group","material sub group","nomor urut","deskripsi material","SA9A00098","spesifikasi","identifikasi","label","UoM","satuan","lokasi","salah ambil","kode ganda"]},"headers":[],"relativePath":"divisi/kode-barang.md","filePath":"divisi/kode-barang.md"}'),d={name:"divisi/kode-barang.md"};function i(l,a,o,s,u,p){return e(),n("div",null,[...a[0]||(a[0]=[r(`<h1 id="kode-barang" tabindex="-1">Kode Barang <a class="header-anchor" href="#kode-barang" aria-label="Permalink to &quot;Kode Barang&quot;">​</a></h1><p class="lead">Setiap material di Gudang Teknik punya <strong>nomor material</strong> (kode barang) dan <strong>deskripsi</strong> yang ditulis menurut standar cataloguing Warehouse BPI. Dengan standar ini, satu jenis material hanya punya satu kode, sehingga barang mudah dicari, tidak ada kode ganda, dan stok bisa dijaga optimal.</p><h2 id="tiga-unsur" tabindex="-1">Tiga unsur <a class="header-anchor" href="#tiga-unsur" aria-label="Permalink to &quot;Tiga unsur&quot;">​</a></h2><table class="tabel-tumpuk" tabindex="0"><thead><tr><th>Unsur</th><th>Penjelasan</th><th>Contoh</th></tr></thead><tbody><tr><td data-label="Unsur"><strong>Nomor material</strong></td><td data-label="Penjelasan">Kode unik 9 karakter yang menjadi identitas satu jenis material</td><td data-label="Contoh"><code>SA9A00098</code></td></tr><tr><td data-label="Unsur"><strong>Deskripsi</strong></td><td data-label="Penjelasan">Nama dan spesifikasi material, ditulis dengan format standar</td><td data-label="Contoh"><code>FORM;OVERTIME;WORK;F4</code></td></tr><tr><td data-label="Unsur"><strong>Identifikasi</strong></td><td data-label="Penjelasan">Proses mengenali barang dari nomor, deskripsi, label, dan lokasinya</td><td data-label="Contoh"><code>SA9A00098</code> di lokasi <code>B.09.02.025</code></td></tr></tbody></table><h2 id="struktur-nomor-material" tabindex="-1">Struktur nomor material <a class="header-anchor" href="#struktur-nomor-material" aria-label="Permalink to &quot;Struktur nomor material&quot;">​</a></h2><p>Nomor material terdiri dari <strong>9 karakter alfanumerik</strong>, disusun bertingkat dari kelompok paling besar ke paling kecil:</p><figure><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>S   A9   A0   0098</span></span>
<span class="line"><span>│   │    │    └── nomor urut (4 digit)</span></span>
<span class="line"><span>│   │    └─────── sub group      → SA9A0</span></span>
<span class="line"><span>│   └──────────── group          → SA9</span></span>
<span class="line"><span>└──────────────── material type  → S = Stationary &amp; Office Supply</span></span></code></pre></div><figcaption>Contoh nomor material SA9A00098 (FORM;OVERTIME;WORK;F4) dari dokumen Material Reservation Gudang Teknik.</figcaption></figure><table class="tabel-tumpuk" tabindex="0"><thead><tr><th>Tingkat</th><th>Panjang</th><th>Isi</th></tr></thead><tbody><tr><td data-label="Tingkat"><strong>Material type</strong></td><td data-label="Panjang">1 huruf</td><td data-label="Isi">Kelompok paling besar, lihat tabel di bawah.</td></tr><tr><td data-label="Tingkat"><strong>Material group</strong></td><td data-label="Panjang">3 karakter</td><td data-label="Isi">Huruf type + 2 karakter. Mengelompokkan nama utama material, misalnya bearing atau valve.</td></tr><tr><td data-label="Tingkat"><strong>Material sub group</strong></td><td data-label="Panjang">5 karakter</td><td data-label="Isi">Kode group + 2 karakter. Menunjukkan jenis, fungsi, atau sifat utamanya, misalnya bearing ball atau bearing cylinder.</td></tr><tr><td data-label="Tingkat"><strong>Nomor urut</strong></td><td data-label="Panjang">4 digit</td><td data-label="Isi">Membedakan material yang spesifik di dalam sub group yang sama.</td></tr></tbody></table><h3 id="material-type" tabindex="-1">Material type <a class="header-anchor" href="#material-type" aria-label="Permalink to &quot;Material type&quot;">​</a></h3><table class="tabel-tumpuk" tabindex="0"><thead><tr><th>Kode</th><th>Type</th><th>Contoh material</th></tr></thead><tbody><tr><td data-label="Kode"><strong>R</strong></td><td data-label="Type">Raw material / pendukung</td><td data-label="Contoh material">HRC, varnish, DOP pipe</td></tr><tr><td data-label="Kode"><strong>E</strong></td><td data-label="Type">Material unit / equipment</td><td data-label="Contoh material">Pump, gear box, blower, motor, valve</td></tr><tr><td data-label="Kode"><strong>P</strong></td><td data-label="Type">Material part</td><td data-label="Contoh material">Bearing, seal, impeller, coupling, bolt &amp; nut</td></tr><tr><td data-label="Kode"><strong>N</strong></td><td data-label="Type">Material non-part / konstruksi</td><td data-label="Contoh material">Steel profile (UNP, H-beam, WF-beam, angle bar, round bar, plate), material sipil</td></tr><tr><td data-label="Kode"><strong>C</strong></td><td data-label="Type">Consumable</td><td data-label="Contoh material">Fuel, oli, grease, pahat (<em>chisel</em>), gas, elektroda las</td></tr><tr><td data-label="Kode"><strong>T</strong></td><td data-label="Type">Tool</td><td data-label="Contoh material">Kunci (<em>wrench</em>), obeng, tool set</td></tr><tr><td data-label="Kode"><strong>S</strong></td><td data-label="Type">Stationary &amp; office supply</td><td data-label="Contoh material">Alat tulis, kertas, meja, kursi, PC</td></tr><tr><td data-label="Kode"><strong>F</strong></td><td data-label="Type">Finish good</td><td data-label="Contoh material">Pipa minyak dan gas, pipa umum</td></tr><tr><td data-label="Kode"><strong>Z</strong></td><td data-label="Type">Other</td><td data-label="Contoh material">Material yang tidak masuk ke type di atas</td></tr></tbody></table><h3 id="contoh-group-dan-sub-group" tabindex="-1">Contoh group dan sub group <a class="header-anchor" href="#contoh-group-dan-sub-group" aria-label="Permalink to &quot;Contoh group dan sub group&quot;">​</a></h3><table class="tabel-tumpuk" tabindex="0"><thead><tr><th>Group</th><th>Arti</th><th>Contoh sub group</th></tr></thead><tbody><tr><td data-label="Group"><code>EA0</code></td><td data-label="Arti">VALVE</td><td data-label="Contoh sub group"><code>EA0A0</code> VALVE;SOLENOID, <code>EA0A1</code> VALVE;DIRECTIONAL</td></tr><tr><td data-label="Group"><code>EA2</code></td><td data-label="Arti">MOTOR</td><td data-label="Contoh sub group"></td></tr><tr><td data-label="Group"><code>PA0</code></td><td data-label="Arti">BEARING</td><td data-label="Contoh sub group"><code>PA0A0</code> BEARING;PILLOW BLOCK, <code>PA0A1</code> BEARING;BALL, <code>PA0A2</code> BEARING;CYLINDER</td></tr><tr><td data-label="Group"><code>NA0</code></td><td data-label="Arti">PLATE</td><td data-label="Contoh sub group"><code>NA0A0</code> PLATE;STAINLESS STEEL, <code>NA0A1</code> PLATE;CARBON STEEL</td></tr><tr><td data-label="Group"><code>CA0</code></td><td data-label="Arti">SAND PAPER</td><td data-label="Contoh sub group"></td></tr></tbody></table><h3 id="contoh-dari-sistem" tabindex="-1">Contoh dari sistem <a class="header-anchor" href="#contoh-dari-sistem" aria-label="Permalink to &quot;Contoh dari sistem&quot;">​</a></h3><table class="tabel-tumpuk" tabindex="0"><thead><tr><th>Nomor material</th><th>Deskripsi</th><th>Type</th></tr></thead><tbody><tr><td data-label="Nomor material"><code>SA9A00098</code></td><td data-label="Deskripsi">FORM;OVERTIME;WORK;F4</td><td data-label="Type">S, stationary &amp; office supply</td></tr><tr><td data-label="Nomor material"><code>CA4A10001</code></td><td data-label="Deskripsi">PAINT;SPRAY;WHITE;300CC;PB101;WITH-MSDS</td><td data-label="Type">C, consumable</td></tr><tr><td data-label="Nomor material"><code>CF3A00010</code></td><td data-label="Deskripsi">SAFETY EQUIPMENT;EAR PLUGS;ROPE;MAX-30/3301130;100PR/CORDED</td><td data-label="Type">C, consumable</td></tr></tbody></table><h2 id="menulis-deskripsi-material" tabindex="-1">Menulis deskripsi material <a class="header-anchor" href="#menulis-deskripsi-material" aria-label="Permalink to &quot;Menulis deskripsi material&quot;">​</a></h2><p>Deskripsi adalah &quot;nama lengkap&quot; sebuah nomor material, sekaligus pembeda antara satu nomor dan nomor lain. Deskripsi harus jelas dan memuat:</p><ul><li>nama material,</li><li>jenis atau bahan material,</li><li>spesifikasi material,</li><li>fungsi atau sifat material.</li></ul><p>Formatnya:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>OBJEK;SPESIFIKASI;FUNGSI/KONDISI</span></span></code></pre></div><p><strong>Objek</strong> adalah nama utama material. Bagian <strong>fungsi/kondisi</strong> boleh tidak diisi.</p><p>Aturan penulisan:</p><ul><li>Semua huruf kapital, <strong>kecuali satuan</strong> (UoM) yang ditulis sesuai standar penulisannya, misalnya <code>kW</code>, <code>Hz</code>, <code>mm</code>, atau <code>l/s</code>.</li><li>Tidak memakai spasi. Antarbagian dipisahkan tanda titik koma (<code>;</code>).</li></ul><p>Contoh:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>BEARING;BALL;6321-2Z</span></span>
<span class="line"><span>MOTOR;AC;15kW;2P;380V;50Hz;3PH;B</span></span>
<span class="line"><span>PUMP;CENTRIFUGAL;H100m;Q150l/s;WATER</span></span></code></pre></div><h2 id="kode-lokasi" tabindex="-1">Kode lokasi <a class="header-anchor" href="#kode-lokasi" aria-label="Permalink to &quot;Kode lokasi&quot;">​</a></h2><p>Nomor material menunjukkan <strong>apa</strong> barangnya, sedangkan kode lokasi menunjukkan <strong>di mana</strong> barang disimpan. Contohnya, <code>SA9A00098</code> disimpan di <code>B.09.02.025</code>, yaitu Blok B, area 09 (alat tulis dan perlengkapan kantor), rak 02. Pembagian area ada di <a href="/WareHouse/alur-kerja/layout-gudang">Layout Gudang</a>.</p><h2 id="mengapa-standar-ini-dibuat" tabindex="-1">Mengapa standar ini dibuat <a class="header-anchor" href="#mengapa-standar-ini-dibuat" aria-label="Permalink to &quot;Mengapa standar ini dibuat&quot;">​</a></h2><p>Standar ini ditetapkan lewat Surat Keputusan CEO No. 196/WRS-BPI/IV/2012, setelah tim katalog spare part meninjau pengodean barang pada April 2012. Sebelumnya, penomoran barang disusun berdasarkan tempat penyimpanan dan huruf awal nama barang, sementara deskripsinya belum terstruktur. Akibatnya, satu barang bisa punya lebih dari satu nomor.</p><p>Tujuan standar ini:</p><ul><li>menyeragamkan cara membuat nomor material, deskripsi, dan satuan (<em>unit of measure</em>),</li><li>mengurangi nomor material ganda,</li><li>mendapatkan stok yang optimal.</li></ul><p>Contoh <code>BRG-MEC-001</code> pada materi presentasi Gudang Teknik adalah contoh sederhana untuk belajar. Kode resmi di sistem memakai struktur 9 karakter di halaman ini.</p><h2 id="kesalahan-yang-sering-terjadi" tabindex="-1">Kesalahan yang sering terjadi <a class="header-anchor" href="#kesalahan-yang-sering-terjadi" aria-label="Permalink to &quot;Kesalahan yang sering terjadi&quot;">​</a></h2><ul><li><strong>Mengandalkan nama saja.</strong> &quot;Bearing&quot; saja ada puluhan ukuran. Selalu cocokkan nomor material <strong>dan</strong> deskripsinya.</li><li><strong>Angka 0 tertukar dengan huruf O.</strong> Nomor material berisi huruf dan angka, misalnya <code>SA9A00098</code>. Bacalah per karakter.</li><li><strong>Label rusak atau hilang.</strong> Jangan menebak. Pisahkan barangnya dan laporkan ke pembimbing.</li><li><strong>Satu barang, dua kode.</strong> Kalau menemukan barang identik dengan nomor berbeda, laporkan. Kode ganda membuat stok tampak lebih sedikit dari kenyataannya.</li><li><strong>Satuan berbeda.</strong> Pastikan satuan di catatan (Bh, Buku, Set, Klg, meter, liter) sama dengan satuan saat barang dihitung.</li></ul><p>Latihan langkah demi langkah ada di tutorial <a href="/WareHouse/tutorial/membaca-kode-barang">Membaca Kode &amp; Spesifikasi</a>. Barang yang belum punya kode diajukan lewat <a href="/WareHouse/sop/kode-material-baru">SOP Permintaan Kode Material Baru</a>.</p>`,34)])])}const b=t(d,[["render",i]]);export{m as __pageData,b as default};
